import random, sys, json, re
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
import gateway

DIR = {"sip:ember@studio.test": ["sip:e1@alias.studio.test", "tel:+12025550121"],
       "sip:desk@sales.test": ["tel:+12025550122"],
       "sip:trunk@trunk.test": []}
ACC = {"session-k": {"primary": "sip:ember@studio.test", "allow": ["sip:desk@sales.test"]}}
GW = {"edge": {"local_domains": ["studio.test","sales.test"], "peers": {"edge": ["studio.test"]}},
      "inside": {"local_domains": [], "peers": {"edge": ["studio.test","sales.test"]}}}
CTX = gateway.Context({"directory": DIR, "accounts": ACC, "gateways": GW})

URIS = ["sip:ember@studio.test","sip:%65mber@STUDIO.TEST.","SIP:e1@alias.studio.test","sip:desk@sales.test",
        "tel:+12025550121","tel:+12025550122","tel:+15555551234","sip:trunk@trunk.test",
        "sip:anonymous@anonymous.invalid","sip:x@y.z","sip:a@b.test","sip:a%2Db@studio.test",
        "sip:ember@studio.test.","sip:Ember@Studio.Test"]
DISP = ["", "Alice ", '"quoted name" ', '"a, b; <x@y>" ', 'A. B-C ', '"esc \\" inside" ', '"dangle\\\\']
TAGP = ["", ";tag=q7", ";tag=Q7", " ; TAG = abc ", ";tag=", ";other=1", ";tag=a;b=c"]

def gen_addr(rng, allow_params=True):
    style = rng.random()
    if style < .35:
        u = rng.choice(URIS); return "<%s%s>" % (rng.choice([" ",""]), (u,)[0]) if False else "<%s>" % u
    if style < .5:
        return "%s%s" % (rng.choice(DISP), "<%s>" % rng.choice(URIS))
    if style < .7:
        u = rng.choice(URIS)
        return u + (rng.choice(TAGP) if allow_params else "")
    u = rng.choice(URIS)
    return "<%s>%s" % (u, rng.choice(TAGP) if allow_params else "")

def gen(cl_ok=True):
    rng = random
    method = rng.choice(["MESSAGE","INVITE"])
    ruri = rng.choice([u for u in URIS if not u.lower().startswith("tel:")])
    lines = ["%s %s SIP/2.0" % (method, ruri)]
    lines.append("From: %s" % gen_addr(rng, True))
    lines.append("To: %s" % gen_addr(rng, True))
    lines.append(rng.choice(["Call-ID","call-id","i"]) + ": " + rng.choice(["c","cid-1","a"*128,"a"*129,"bad id",""]))
    lines.append("CSeq: %s %s" % (rng.choice(["1","0001","0","2147483648","9"*30,"1  MESSAGE","\t"]), method))
    for nm in ["P-Asserted-Identity","P-Preferred-Identity","Remote-Party-ID","Privacy","Content-Type","Via","Authorization","X-Foo"]:
        if rng.random() < .45:
            if nm == "P-Asserted-Identity":
                k = rng.randint(1,3)
                lines.append(nm + ": " + ",".join("<%s>" % rng.choice(URIS) for _ in range(k)))
            elif nm == "Privacy":
                lines.append(nm + ": " + rng.choice(["id","none","ID","NoNe","yes","id,none",""]))
            elif nm == "Content-Type":
                lines.append(nm + ": " + rng.choice(["text/plain","application/x-test","", "a\tb"]))
            elif nm in ("P-Preferred-Identity","Remote-Party-ID"):
                lines.append(nm + ": " + gen_addr(rng, False))
            else:
                lines.append(nm + ": " + rng.choice(['<sip:a@b>;tag=x','"y"','z']))
        if rng.random() < .1:
            lines.append(rng.choice([" ","\t"]) + "continuation " + rng.choice(URIS))
    body = rng.choice(["hello","","x"*7,"a\r\nb","tab\there"])
    n = len(body) if cl_ok else rng.randint(0,9)
    lines.append(rng.choice(["Content-Length","l"]) + ": " + rng.choice(["","%d"%n,"0"*4+"%d"%n,"%d"%n,"x"]))
    lines.append(rng.choice(["Content-Length","l"]) + ": " + "%d"%n if rng.random()<.1 else None)
    lines = [l for l in lines if l is not None]
    return "%s\r\n\r\n%s" % ("\r\n".join(lines), body)

def mutate(text):
    rng = random
    if not text: return text
    k = rng.randint(1,3)
    chars = list(text)
    for _ in range(k):
        op = rng.random(); i = rng.randrange(len(chars))
        if op < .3: chars[i] = rng.choice(list('\r\n\t "<>;,=\\%*!@\'.0123456789abcdefSIPTel:\x00\x7f\u00e9'))
        elif op < .5: del chars[i]
        elif op < .8: chars.insert(i, rng.choice(list('\r\n\t "<>;,=\\%*!@.\x00\u00e9')))
        else: chars[i:i] = list(rng.choice(["\r\n\r\n","sip:a@b.c","Content-Length: 0\r\n","From: <sip:a@b>","P-Asserted-Identity: <sip:a@b>","  x\r\n"]))
    return "".join(chars)

jobs_seen = 0
reasons = {}
internal = []
random.seed(4242)
for t in range(40000):
    text = gen()
    if random.random() < .5: text = mutate(text)
    if len(text) > 32768: continue
    gw = random.choice(["edge","inside","nope"])
    ing = random.choice([{"kind":"local","subject":"session-k"},{"kind":"local","subject":"nope"},
                         {"kind":"peer","name":"edge"},{"kind":"peer","name":"nope"},{"kind":"untrusted"}])
    job = {"gateway":gw,"ingress":ing,"trusted_out":random.random()<.5,"raw":text}
    jobs_seen += 1
    try:
        res = gateway.handle(job,0,[],CTX)
    except gateway.Reject as exc:
        reasons[exc.reason] = reasons.get(exc.reason,0)+1
        continue
    except Exception as exc:
        internal.append((type(exc).__name__, str(exc)[:80], text[:200])); reasons["crash"]=reasons.get("crash",0)+1
        continue
    reasons["accept"] = reasons.get("accept",0)+1
    # sanity: accepted wire must reparse
    cut = res["wire"].find("\r\n\r\n")
    hdr = res["wire"][:cut].split("\r\n")
    if hdr[0].split(" ")[2] != "SIP/2.0": internal.append(("rline", res["wire"][:100]))
    for i, nm in enumerate(["From","To","Call-ID","CSeq","Privacy"]):
        if not hdr[1+i].startswith(nm+": "): internal.append(("order",hdr))
    if hdr[-1] != "Content-Length: %d" % len(res["wire"][cut+4:]): internal.append(("cl", hdr[-1]))
    if res["identity"] not in DIR: internal.append(("ident", res["identity"]))
    if res["private"] and "<sip:anonymous@anonymous.invalid>" not in hdr[1]: internal.append(("priv", hdr[1]))
    if not res["private"] and hdr[1] != "From: <%s>" % res["identity"]: internal.append(("from", hdr[1]))
    # idempotence at same local gateway
    j2 = {"gateway":"edge","ingress":{"kind":"local","subject":"session-k"},"trusted_out":job["trusted_out"],"raw":res["wire"]}
    try:
        r2 = gateway.handle(j2,0,[],CTX)
        if r2["wire"] != res["wire"]: internal.append(("not idempotent", res["wire"][:120], r2["wire"][:120]))
    except gateway.Reject as exc:
        internal.append(("reparse %s" % exc.reason, res["wire"][:160]))
    except Exception as exc:
        internal.append(("reparse crash", type(exc).__name__))
print("jobs", jobs_seen, reasons)
print("problems", len(internal))
seen=set()
for p in internal:
    if p[0] in seen: continue
    seen.add(p[0]); print(json.dumps(p)[:500])
PYEOF
